<?php $title='Candidates'; require 'header.php'; $q=trim($_GET['q']??'');$status=$_GET['status']??'';$sql="SELECT c.*,j.title FROM candidates c JOIN jobs j ON j.id=c.job_id WHERE 1";$types='';$vals=[];if($q){$sql.=" AND (c.first_name LIKE CONCAT('%',?,'%') OR c.last_name LIKE CONCAT('%',?,'%') OR c.email LIKE CONCAT('%',?,'%') OR c.application_no LIKE CONCAT('%',?,'%'))";$types.='ssss';array_push($vals,$q,$q,$q,$q);}if($status){$sql.=" AND c.status=?";$types.='s';$vals[]=$status;}$sql.=" ORDER BY c.created_at DESC";$st=db()->prepare($sql);if($types)$st->bind_param($types,...$vals);$st->execute();$rows=stmt_rows($st);?>
<div class="admin-head"><div><span class="eyebrow">TALENT PIPELINE</span><h1>All candidates</h1></div></div><form class="admin-filters"><input name="q" value="<?=e($q)?>" placeholder="Search name, email or application #"><select name="status"><option value="">All statuses</option><?php foreach(['new','screening','interview','offer','hired','rejected'] as $s):?><option value="<?=$s?>" <?=$status===$s?'selected':''?>><?=e(status_label($s))?></option><?php endforeach;?></select><button class="btn dark">Filter</button></form>
<section class="admin-panel"><table><thead><tr><th>Candidate</th><th>Role</th><th>Status</th><th>Application</th><th>Received</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><strong><?=e($r['first_name'].' '.$r['last_name'])?></strong><small><?=e($r['email'])?></small></td><td><?=e($r['title'])?></td><td><span class="status-pill <?=e($r['status'])?>"><?=e(status_label($r['status']))?></span></td><td><a href="candidate.php?id=<?=$r['id']?>"><?=e($r['application_no'])?></a></td><td><?=e(date('M j, Y',strtotime($r['created_at'])))?></td></tr><?php endforeach;?></tbody></table></section><?php require 'footer.php'; ?>